enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/6/\",\"title\":\"Chapter Six: Dhyāna-yoga\"}],\"url_path\":\"/en/library/bg/6/47/\",\"bb\":1827,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/6/46/\",\"title\":\"TEXT 46\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/7/\",\"title\":\"Chapter Seven\",\"has_advanced_view\":true,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":2066,\"bb\":568149,\"url_path\":\"/en/library/bg/6/47/devanagari/\",\"body_final\":\"योगिनामपि सर्वेषां मद्ग‍तेनान्तरात्मना ।
श्रद्धावान्भजते यो मां स मे युक्ततमो मत: ॥ ४७ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2067,\"bb\":1828,\"url_path\":\"/en/library/bg/6/47/b1828/\",\"body_value\":\"yoginām api sarveṣāṁ
mad-gatenāntar-ātmanā
śraddhāvān bhajate yo māṁ
sa me yukta-tamo mataḥ\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":2068,\"bb\":1829,\"url_path\":\"/en/library/bg/6/47/b1829/\",\"shadow_value\":\"yoginām – of yogīs; api – also; sarveṣām – all types of; mat-gatena – abiding in Me, always thinking of Me; antaḥ-ātmanā – within himself; śraddhā-vān – in full faith; bhajate – renders transcendental loving service; yaḥ – one who; mām – to Me (the Supreme Lord); saḥ – he; me – by Me; yukta-tamaḥ – the greatest yogī; mataḥ – is considered.\",\"word_for_word_value\":[{\"word\":\"yoginām\",\"translation\":\"of yogīs\"},{\"word\":\"api\",\"translation\":\"also\"},{\"word\":\"sarveṣām\",\"translation\":\"all types of\"},{\"word\":\"mat-gatena\",\"translation\":\"abiding in Me, always thinking of Me\"},{\"word\":\"antaḥ-ātmanā\",\"translation\":\"within himself\"},{\"word\":\"śraddhā-vān\",\"translation\":\"in full faith\"},{\"word\":\"bhajate\",\"translation\":\"renders transcendental loving service\"},{\"word\":\"yaḥ\",\"translation\":\"one who\"},{\"word\":\"mām\",\"translation\":\"to Me (the Supreme Lord)\"},{\"word\":\"saḥ\",\"translation\":\"he\"},{\"word\":\"me\",\"translation\":\"by Me\"},{\"word\":\"yukta-tamaḥ\",\"translation\":\"the greatest yogī\"},{\"word\":\"mataḥ\",\"translation\":\"is considered\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":2069,\"bb\":1830,\"url_path\":\"/en/library/bg/6/47/b1830/\",\"body_value\":\"And of all yogīs, the one with great faith who always abides in Me, thinks of Me within himself and renders transcendental loving service to Me – he is the most intimately united with Me in yoga and is the highest of all. That is My opinion.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2070,\"bb\":1831,\"url_path\":\"/en/library/bg/6/47/b1831/\",\"body_value\":\"The word bhajate is significant here. Bhajate has its root in the verb bhaj, which is used when there is need of service. The English word “worship” cannot be used in the same sense as bhaj. Worship means to adore, or to show respect and honor to the worthy one. But service with love and faith is especially meant for the Supreme Personality of Godhead. One can avoid worshiping a respectable man or a demigod and may be called discourteous, but one cannot avoid serving the Supreme Lord without being thoroughly condemned. Every living entity is part and parcel of the Supreme Personality of Godhead, and thus every living entity is intended to serve the Supreme Lord by his own constitution. Failing to do this, he falls down. The Bhāgavatam (11.5.3) confirms this as follows:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2071,\"bb\":1832,\"url_path\":\"/en/library/bg/6/47/b1832/\",\"body_value\":\"ya eṣāṁ puruṣaṁ sākṣād
ātma-prabhavam īśvaram
na bhajanty avajānanti
sthānād bhraṣṭāḥ patanty adhaḥ\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2072,\"bb\":1833,\"url_path\":\"/en/library/bg/6/47/b1833/\",\"body_value\":\"“Anyone who does not render service and neglects his duty unto the primeval Lord, who is the source of all living entities, will certainly fall down from his constitutional position.”\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2073,\"bb\":1834,\"url_path\":\"/en/library/bg/6/47/b1834/\",\"body_value\":\"In this verse also the word bhajanti is used. Therefore, bhajanti is applicable to the Supreme Lord only, whereas the word “worship” can be applied to demigods or to any other common living entity. The word avajānanti, used in this verse of Śrīmad-Bhāgavatam, is also found in the Bhagavad-gītā. Avajānanti māṁ mūḍhāḥ: “Only the fools and rascals deride the Supreme Personality of Godhead, Lord Kṛṣṇa.” Such fools take it upon themselves to write commentaries on the Bhagavad-gītā without an attitude of service to the Lord. Consequently they cannot properly distinguish between the word bhajanti and the word “worship.”\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2074,\"bb\":1835,\"url_path\":\"/en/library/bg/6/47/b1835/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2075,\"bb\":1836,\"url_path\":\"/en/library/bg/6/47/b1836/\",\"body_value\":\"It is by great fortune that one comes to Kṛṣṇa consciousness on the path of bhakti-yoga to become well situated according to the Vedic direction. The ideal yogī concentrates his attention on Kṛṣṇa, who is called Śyāmasundara, who is as beautifully colored as a cloud, whose lotuslike face is as effulgent as the sun, whose dress is brilliant with jewels, and whose body is flower-garlanded. Illuminating all sides is His gorgeous luster, which is called the brahma-jyotir. He incarnates in different forms such as Rāma, Nṛsiṁha, Varāha and Kṛṣṇa, the Supreme Personality of Godhead, and He descends like a human being, as the son of mother Yaśodā, and He is known as Kṛṣṇa, Govinda and Vāsudeva. He is the perfect child, husband, friend and master, and He is full with all opulences and transcendental qualities. If one remains fully conscious of these features of the Lord, he is called the highest yogī.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2076,\"bb\":1837,\"url_path\":\"/en/library/bg/6/47/b1837/\",\"body_value\":\"This stage of highest perfection in yoga can be attained only by bhakti-yoga, as is confirmed in all Vedic literature:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2077,\"bb\":1838,\"url_path\":\"/en/library/bg/6/47/b1838/\",\"body_value\":\"yasya deve parā bhaktir
yathā deve tathā gurau
tasyaite kathitā hy arthāḥ
prakāśante mahātmanaḥ\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2078,\"bb\":1839,\"url_path\":\"/en/library/bg/6/47/b1839/\",\"body_value\":\"“Only unto those great souls who have implicit faith in both the Lord and the spiritual master are all the imports of Vedic knowledge automatically revealed.” (Śvetāśvatara Upaniṣad 6.23)\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2079,\"bb\":1840,\"url_path\":\"/en/library/bg/6/47/b1840/\",\"body_value\":\"Bhaktir asya bhajanaṁ tad ihāmutropādhi-nairāsyenāmuṣmin manaḥ-kalpanam, etad eva naiṣkarmyam. “Bhakti means devotional service to the Lord which is free from desire for material profit, either in this life or in the next. Devoid of such inclinations, one should fully absorb the mind in the Supreme. That is the purpose of naiṣkarmya.” (Gopāla-tāpanī Upaniṣad 1.15)\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2080,\"bb\":1841,\"url_path\":\"/en/library/bg/6/47/b1841/\",\"body_value\":\"These are some of the means for performance of bhakti, or Kṛṣṇa consciousness, the highest perfectional stage of the yoga system.\"},{\"type\":\"content.Record\",\"title\":\"paragraph_end\",\"id\":2081,\"bb\":1842,\"url_path\":\"/en/library/bg/6/47/b1842/\",\"body_value\":\"Thus end the Bhaktivedanta Purports to the Sixth Chapter of the Śrīmad Bhagavad-gītā in the matter of Dhyāna-yoga.\"}]}],\"short_title\":\"Bg. 6.47\",\"medium_title\":\"Bhagavad-gītā As It Is 6.47\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L26\",\"$L27\",\"$L28\"]}]\n"])self.__next_f.push([1,"2a:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n30