/\"},{\"display_name\":\"Polski (Polish)\",\"language_code\":\"pl\",\"enabled\":true,\"url_path\":\"/pl/library/bg/7/1/\"},{\"display_name\":\"Português (Portuguese)\",\"language_code\":\"pt-br\",\"enabled\":true,\"url_path\":\"/pt-br/library/bg/7/1/\"},{\"display_name\":\"Русский (Russian)\",\"language_code\":\"ru\",\"enabled\":true,\"url_path\":\"/ru/library/bg/7/1/\"},{\"display_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/7/1/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/7/1/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/7/1/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/7/\",\"title\":\"Chapter Seven: Knowledge of the Absolute\"}],\"url_path\":\"/en/library/bg/7/1/\",\"bb\":1845,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/7/\",\"title\":\"Chapter Seven\",\"has_advanced_view\":true,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/7/2/\",\"title\":\"TEXT 2\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":2084,\"bb\":568150,\"url_path\":\"/en/library/bg/7/1/devanagari/\",\"body_final\":\"श्रीभगवानुवाच
मय्यासक्तमना: पार्थ योगं युञ्जन्मदाश्रय: ।
असंशयं समग्रं मां यथा ज्ञास्यसि तच्छृणु ॥ १ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2085,\"bb\":1847,\"url_path\":\"/en/library/bg/7/1/b1847/\",\"body_value\":\"śrī-bhagavān uvāca
mayy āsakta-manāḥ pārtha
yogaṁ yuñjan mad-āśrayaḥ
asaṁśayaṁ samagraṁ māṁ
yathā jñāsyasi tac chṛṇu\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":2086,\"bb\":1848,\"url_path\":\"/en/library/bg/7/1/b1848/\",\"shadow_value\":\"śrī-bhagavān uvāca – the Supreme Lord said; mayi – to Me; āsakta-manāḥ – mind attached; pārtha – O son of Pṛthā; yogam – self-realization; yuñjan – practicing; mat-āśrayaḥ – in consciousness of Me (Kṛṣṇa consciousness); asaṁśayam – without doubt; samagram – completely; mām – Me; yathā – how; jñāsyasi – you can know; tat – that; śṛṇu – try to hear.\",\"word_for_word_value\":[{\"word\":\"śrī-bhagavān uvāca\",\"translation\":\"the Supreme Lord said\"},{\"word\":\"mayi\",\"translation\":\"to Me\"},{\"word\":\"āsakta-manāḥ\",\"translation\":\"mind attached\"},{\"word\":\"pārtha\",\"translation\":\"O son of Pṛthā\"},{\"word\":\"yogam\",\"translation\":\"self-realization\"},{\"word\":\"yuñjan\",\"translation\":\"practicing\"},{\"word\":\"mat-āśrayaḥ\",\"translation\":\"in consciousness of Me (Kṛṣṇa consciousness)\"},{\"word\":\"asaṁśayam\",\"translation\":\"without doubt\"},{\"word\":\"samagram\",\"translation\":\"completely\"},{\"word\":\"mām\",\"translation\":\"Me\"},{\"word\":\"yathā\",\"translation\":\"how\"},{\"word\":\"jñāsyasi\",\"translation\":\"you can know\"},{\"word\":\"tat\",\"translation\":\"that\"},{\"word\":\"śṛṇu\",\"translation\":\"try to hear\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":2087,\"bb\":1849,\"url_path\":\"/en/library/bg/7/1/b1849/\",\"body_value\":\"The Supreme Personality of Godhead said: Now hear, O son of Pṛthā, how by practicing yoga in full consciousness of Me, with mind attached to Me, you can know Me in full, free from doubt.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2088,\"bb\":1850,\"url_path\":\"/en/library/bg/7/1/b1850/\",\"body_value\":\"In this Seventh Chapter of Bhagavad-gītā, the nature of Kṛṣṇa consciousness is fully described. Kṛṣṇa is full in all opulences, and how He manifests such opulences is described herein. Also, four kinds of fortunate people who become attached to Kṛṣṇa and four kinds of unfortunate people who never take to Kṛṣṇa are described in this chapter.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2089,\"bb\":1851,\"url_path\":\"/en/library/bg/7/1/b1851/\",\"body_value\":\"$25\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2090,\"bb\":1852,\"url_path\":\"/en/library/bg/7/1/b1852/\",\"body_value\":\"One should therefore begin yoga practice as directed in the last verse of the Sixth Chapter. Concentration of the mind upon Kṛṣṇa the Supreme is made possible by prescribed devotional service in nine different forms, of which śravaṇam is the first and most important. The Lord therefore says to Arjuna, tac chṛṇu, or “Hear from Me.” No one can be a greater authority than Kṛṣṇa, and therefore by hearing from Him one receives the greatest opportunity to become a perfectly Kṛṣṇa conscious person. One has therefore to learn from Kṛṣṇa directly or from a pure devotee of Kṛṣṇa – and not from a nondevotee upstart, puffed up with academic education.\"},{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":2091,\"bb\":1853,\"url_path\":\"/en/library/bg/7/1/b1853/\",\"body_value\":\"In the Śrīmad-Bhāgavatam this process of understanding Kṛṣṇa, the Supreme Personality of Godhead, the Absolute Truth, is described in the Second Chapter of the First Canto as follows:\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":2092,\"bb\":1854,\"url_path\":\"/en/library/bg/7/1/b1854/\",\"body_value\":\"śṛṇvatāṁ sva-kathāḥ kṛṣṇaḥ
puṇya-śravaṇa-kīrtanaḥ
hṛdy antaḥ-stho hy abhadrāṇi
